export class Counter {                 // single owner of the state
  #total = 0;
  #chain = Promise.resolve();
  #serial(fn) {                        // queued: one mutation at a time
    const run = this.#chain.then(fn, fn);
    this.#chain = run.catch(() => {}); // keep the queue alive after a rejection
    return run;
  }
  add(delta) { return this.#serial(() => (this.#total += delta)); }
  snapshot() { return this.#serial(() => this.#total); }
}
